import React from 'react';

export default function Sidebar({ setCurrentPage, currentPage }) {
  const menuItems = [
    { name: 'Dashboard', icon: '📊' },
    { name: 'Overview', icon: '👁️‍🗨️' },
    { name: 'Students', icon: '👨‍🎓' },
    { name: 'Teachers & Classes', icon: '🏫' },
    { name: 'Reports', icon: '📈' },
    { name: 'Settings', icon: '⚙️' },
  ];

  return (
    <div style={{ 
      width: '260px', 
      backgroundColor: '#1e3a8a', 
      color: '#ffffff', 
      height: '100vh', 
      padding: '25px 15px',
      boxShadow: '4px 0 10px rgba(0, 0, 0, 0.1)',
      display: 'flex',
      flexDirection: 'column',
      fontFamily: "'Segoe UI', Roboto, sans-serif"
    }}>
      {/* Logo Section */}
      <div style={{ 
        display: 'flex', 
        alignItems: 'center', 
        gap: '12px', 
        marginBottom: '45px',
        paddingLeft: '10px'
      }}>
        <span style={{ fontSize: '24px' }}>📚</span>
        <h2 style={{ fontSize: '22px', fontWeight: '600', margin: 0, letterSpacing: '0.5px' }}>Libary</h2>
      </div>

      {/* Menu Items */}
      <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
        {menuItems.map((item, i) => {
          const isActive = currentPage === item.name || (currentPage === 'Classes' && item.name === 'Teachers & Classes');
          
          return (
            <div 
              key={i} 
              onClick={() => {
                if (item.name === 'Teachers & Classes') {
                  setCurrentPage('Classes');
                } else {
                  setCurrentPage(item.name);
                }
              }}
              style={{ 
                padding: '12px 16px', 
                borderRadius: '8px',
                cursor: 'pointer', 
                display: 'flex', 
                alignItems: 'center', 
                gap: '15px',
                transition: 'all 0.3s ease',
                backgroundColor: isActive ? 'rgba(255, 255, 255, 0.15)' : 'transparent',
                fontWeight: isActive ? '600' : '400',
                opacity: isActive ? 1 : 0.85,
              }}
              onMouseEnter={(e) => {
                if(!isActive) {
                  e.currentTarget.style.backgroundColor = 'rgba(255, 255, 255, 0.08)';
                  e.currentTarget.style.opacity = '1';
                }
              }}
              onMouseLeave={(e) => {
                if(!isActive) {
                  e.currentTarget.style.backgroundColor = 'transparent';
                  e.currentTarget.style.opacity = '0.85';
                }
              }}
            >
              <span style={{ fontSize: '18px', display: 'flex', alignItems: 'center' }}>{item.icon}</span> 
              <span style={{ fontSize: '15px' }}>{item.name}</span>
            </div>
          );
        })}
      </div>
    </div>
  );
}
